const devConfig = {
    Auth: {
        region: process.env.REACT_APP_AWS_REGION || 'us-east-1',
        userPoolId: process.env.REACT_APP_USER_POOL_ID || 'us-east-1_xxxxxxxx',
        userPoolWebClientId: process.env.REACT_APP_USER_POOL_WEB_CLIENT_ID || 'xxxxxxxxxxxxxxxxxxxxxxxxxx',
        mandatorySignIn: true,
        cookieStorage: {
            domain: 'localhost',
            path: '/',
            expires: 365,
            secure: false
        }
    },
    API: {
        endpoints: [
            {
                name: 'api',
                endpoint: process.env.REACT_APP_API_URL || 'https://xxxxxxxx.execute-api.us-east-1.amazonaws.com/dev',
                region: process.env.REACT_APP_AWS_REGION || 'us-east-1'
            }
        ]
    }
};

export default devConfig;
